import React from 'react';
import styled from 'styled-components';

import Spacings from '@dynatrace/strato-design-tokens/spacings';
import { AutocompleteSuggestionPart } from '@dynatrace-sdk/client-query';

import { DocumentationLink } from './DocumentationLink.js';
import { CodeSnippet } from '../../../content/code-snippet/CodeSnippet.js';
import { Flex } from '../../../layouts-core/flex/Flex.js';
import { Text } from '../../../typography/Text.js';

const StyledSectionInfo = styled(Text)`
  display: inline;
  margin-right: 0.5ch;
`;

const StyledCodeSnippet = styled(CodeSnippet)`
  margin-top: ${Spacings.Size4};
`;

type Props = {
  suggestionPart: AutocompleteSuggestionPart;
};

export const SuggestionPart = (props: Props) => {
  const { suggestionPart } = props;

  return (
    <Flex flexDirection="column" gap={0}>
      <StyledSectionInfo textStyle="base">
        {suggestionPart.info}{' '}
        <DocumentationLink suggestionPart={suggestionPart} />
      </StyledSectionInfo>

      {suggestionPart.synopsis && (
        <StyledCodeSnippet
          language="dql"
          showLineNumbers={false}
          allowCopy={false}
          lineBreaks
        >
          {suggestionPart.synopsis}
        </StyledCodeSnippet>
      )}
    </Flex>
  );
};
